"""Original liver abscess and hydatid questions."""
from qbank_authoring import question,ref,finalize
PY=ref('Pyogenic Liver Abscess: Clinical Review','https://doi.org/10.1136/flgastro-2013-100371')
AM=ref('AASLD Clinical Liver Disease: Amebic Liver Abscess','https://pmc.ncbi.nlm.nih.gov/articles/PMC6490646/')
